// ---------- 場面8　森の婆の庵 ----------
T.s8 = async () => {
  await talk(`
〔卓に湯のみが二つ、椅子が二脚。一脚には誰も座らず、うっすら埃。壁に、大きな麦わら帽。〕
ネネ：カイ。それに…ほう。
ネネ：人間の娘とは、どういう風の吹き回しじゃ。
カイ：客だ、婆。月夜草を採りに来た。
リゼット：はじめまして。薬売りのリゼットです。
ネネ：ふん。わしはネネ。里じゃ魔女と呼ばれとる。
ネネ：薬売りが、命がけで草一本かい。
リゼット：効くものなら、どこへでも探しに行きます。
ネネ：…その目は、草を探しとる目じゃないね。
リゼット：あら。何を探している目かしら。
ネネ：さあてね。当人にも、まだ分かっとらん目じゃ。
〔二人がしばらく見合う。〕`);
  scene("s8");
  await talk(`
〔少し遅れて、ムクが入ってくる。〕
ネネ：月夜草ならヌシの沼じゃ。
ネネ：ただし今、沼のヌシは機嫌が悪い。
ネネ：北から来た者らが騒ぐんで、眠れんのじゃと。
ネネ：沼への道も荒れとる。狼が群れとるよ。
ネネ：二人では骨が折れる。ムク、案内しておやり。
ムク：ぼくが？…人間と？
リゼット：案内してくれたら、飴をあげるわ。
ムク：あめ！…行く。こっち！
カイ：ムク。これを持っていけ。
〔カイが、小さな光を差し出す。〕
ムク：どんぐりの心だ！受け取る！`);
  setS(8); scene("");
  await FD.joinMember(2);
  // 持ち物のドングリ兵の心を、ムクに宿す
  const m = G().party[2];
  if (m && !m.heart) { if (G().hearts.donguri > 0) G().hearts.donguri--; m.heart = "donguri"; }
  await sys("ムクが「ドングリ兵の心」を宿した。", "ムクは素早く、数の多い相手に強い。");
  await talk(`
リゼット：おばあさま。一つだけ。
リゼット：魔王が蘇ったという話、ご存じ？
ネネ：…魔王、ね。
ネネ：森の者は、誰も聞いとらんよ。
ネネ：聞いとらんものは、おらんのと同じじゃ。
リゼット：そう。…そうよね。
〔リゼットが、空の椅子に目をやる。〕
リゼット：こちらは、どなたの席？
ネネ：亭主のじゃ。
ネネ：三百年、便りの一つも寄こさん亭主のな。
リゼット：三百年…。気の長いお話ね。
ネネ：座るでないよ。埃も払わんでええ。
ネネ：空けてあるのには、訳があるんじゃ。`);
  await sys("庵の寝床では、いつでも休める。");
};
