async function s10boat() {
  G().away = [2]; F().mukuStay = 1; A.sync();
  await talk(`
〔ムクは岸に残る。〕
ムク：カイ兄、気をつけて。`);
  await move("river", 6, 14, 1, "s10b");
  await talk(`
リゼット：正直に言うわ。私、追われてるの。
リゼット：黒い外套の人たちよ。都から来たの。
カイ：何をした。
リゼット：まだ何も。これからするのよ。
リゼット：お願い。この帆布の下に隠して。`);
  if (await pick(["隠す", "先にわけを話せ"]) === 0) await talk(`
カイ：…乗せた客は、岸まで渡す。
リゼット：ありがとう。その決まり、好きよ。`);
  else await talk(`
カイ：わけを話せ。
リゼット：岸に着いたら全部話す。約束するわ。
リゼット：私、約束は破らないの。嘘はつくけど。
カイ：…入れ。`);
  await talk(`〔リゼットが、帆布の下にもぐる。〕`);
  G().away = [1, 2];
  await move("sandbar", 6, 12, 3, "s10c");
  await talk(`
〔中州。ホップとマーサが手を振っている。〕
ホップ：カイ！鐘が鳴ったぞ、早く乗せてくれ！`);
  await move("river", 6, 14, 1, "s10c");
  await talk(`
〔マーサが、帆布の上に腰を下ろそうとする。〕
マーサ：よっこいしょ…あら、何だいこの荷物。
カイ：…網だ。濡れてる。座るな。
マーサ：おや、すまないね。
〔帆布が、わずかに震えた。〕`);
  await move("ferry", 10, 17, 1, "s10", "dusk");
  await talk(`
〔桟橋に、黒い外套の男たち。向かい合って、ドナと村人たち。〕
シグ：栗色の髪の娘だ。三つ編み、背に薬箱。
シグ：この村を通ったはずだ。
ドナ：さあねえ。年寄りは目が悪くてね。
シグ：隠し立てすれば、家を一軒ずつ調べる。
ドナ：調べとくれ。豆と網しか出てこんよ。
〔舟が着く。傷の男が、カイを見る。〕
シグ：渡し守か。今日、誰を渡した。`);
  if (await pick(["畑の夫婦だけだ", "……"]) === 0) await talk(`
カイ：畑の夫婦だけだ。`);
  else await talk(`
〔カイは黙って、棹を拭く。〕
シグ：…口のきけん男か。
ドナ：無口なだけさ。客は畑の二人だよ。`);
  await talk(`
ホップ：そ、そうだ。おれたちだけだ。なあ。
マーサ：ええ、ええ。豆を採ってただけで。
ティム：でも、ぼく朝に見たよ。きれいな
ドナ：ティム。おまえは鶏に餌をやっといで。
ティム：…はあい。
〔傷の男がティムとドナを見比べ、それから川向こうの森を見る。〕
シグ：あの森は。
ドナ：魔物の森さ。村の者は誰も近づかん。
シグ：…今夜はこの村に泊まる。
シグ：夜明けに森を調べる。舟を出してもらうぞ。
カイ：……。
シグ：一つ言っておく。
シグ：娘を見つけても、指一本触れるな。
シグ：傷一つつけず連れ戻せ、との命だ。`);
  await A.fadeOut(); scene("s10d"); A.fadeIn(); await wait(300);
  await talk(`
〔黒外套たちは、村の広場へ去っていった。ドナが小声で言う。〕
ドナ：カイ。あんた、森の岸に着けたね。
カイ：…すまない。
ドナ：謝るのは後だ。その網、小屋に運んどきな。
ドナ：濡れた網は、夜まで干しとくもんだよ。`);
  setS(12); scene(""); G().home = { map: "hut", x: 3, y: 3 };
}
