ネネ：…ふん。その娘の入れ知恵じゃな。
リゼット：ええ。私の考えです。
ネネ：ようできた策じゃ。できすぎとる。
ネネ：カイ。おまえは、どうしたい。`);
  if (await pick(["森を守りたい", "北のことが気になる"]) === 0) await talk(`
カイ：行く。森を守れるなら。`);
  else await talk(`
カイ：北が気になる。あの子の里が焼けた。`);
  await talk(`
ネネ：そうかい。
ネネ：なら、行っておいで。
ネネ：川の向こうを見ておいで。
ネネ：北で何が起きとるのか。魔王とやらが何なのか。
ネネ：その目で見て、婆に教えておくれ。
カイ：…ああ。
ムク：ぼくも行く！
ネネ：おまえは留守番じゃ。
ムク：やだ！カイ兄、一人だと手が足りないんだよ！
ムク：ぼく、嘘つけないけど、だまるのはできる！
リゼット：おばあさま。角なら隠せます。
リゼット：庵の壁の帽子、お借りしても？`);
  F().hat = 1; apply(); scene("s11d");
  await talk(`
〔ネネが黙って、麦わら帽を差し出す。リゼットがムクにかぶせる。角がすっぽり隠れる。〕
リゼット：ほら。ただの、帽子の大きい子よ。
ネネ：…頭の回る娘じゃ。
ネネ：ムク。帽子を取るでないよ。寝るときもじゃ。
ムク：うん！`);
  G().away = []; F().mukuStay = 0; scene("s11e");
  await sys("ムクが仲間に戻った。");
  await talk(`
ネネ：カイ。一つだけ覚えておき。
ネネ：渡し守は、川では死なん。
ネネ：迷ったら川を探せ。水はここへ流れてくる。
カイ：覚えておく。
〔カイとムクが舟へ向かう。ネネが、リゼットだけを呼び止める。〕
ネネ：娘さん。
