モーリス：は、はあ。橋が通れるようになれば、何でも。
ダッカ：なんだ、この小娘は。
リゼット：ただの薬売りよ。十日は待てない客なの。`);
  setS(19);
  await A.fadeOut(); A.enter("harune", 14, 9, 0); A.fadeIn(); await wait(300);
  await talk(`
