  await FD.battle({ nm: "古い見張り塔", bg: "stone", foes: [{ k: "ishikoro", c: 0, r: 0 }, { k: "ishikoro", c: 0, r: 1 }, { k: "ishikoro", c: 0, r: 2 }], tier: 2, retry: 1, noHeart: 1, drops: [] });
  G().hearts.ishikoro = (G().hearts.ishikoro || 0) + 1;
