ガルム：…落としては、いない。
ガルム：…わしが、立っただけだ。
リゼット：立った…？
ガルム：…わしは、橋だった。真ん中の、ひとつ分だ。
ガルム：…三百年、寝そべっていた。
ガルム：…人も、獣も、渡した。背中を踏ませた。
