商人：きょ、巨人だ！下りてきたぞ！
ダッカ：槍を持て！隊列を、いや、下がれ下がれ！
リゼット：落ち着いて。話はついたわ。
モーリス：は、話？魔物と？
リゼット：ええ。橋は今夜のうちに直るわ。この人が積むの。
