ベラ：橋が直るってんで、気の早い客が発ったのさ。
〔ベラが去る。〕
カイ：ブラム。北の話を聞かせてくれ。
ブラム：…斥候だった。遠征軍の、いちばん前だ。
ブラム：氷の峠を越えて、影みたいな原を抜けた。
ブラム：城があった。魔王の城だ。地図どおりにな。
