ブラム：それも、一年や二年の留守じゃねえ。
リゼット：…それを、報告したのね。
ブラム：したさ。「魔王は奥に潜む」に書き直された。
ブラム：三度言ったら、士気を乱す罪だとよ。
ブラム：軍法会議の前の晩に、逃げた。
ブラム：途中で矢を食らって、塔の下で倒れた。
ブラム：あとは見てのとおりだ。
ムク：森のみんなも言ってた。魔王さま、聞いてないって。
ブラム：…なんだと？
カイ：森の継ぐ民は、誰も知らなかった。
ブラム：魔物も知らねえ魔王、か。
ブラム：じゃあ俺たちは一年、何と戦ってたんだ。
リゼット：……。
カイ：神託が、まちがっているのか。
ブラム：しっ。それを口にしたら首が飛ぶ。
ブラム：だがな。俺は見たものしか信じねえ。
ブラム：城は空だった。それだけは本当だ。
〔リゼットは杯を見つめている。やがて顔を上げる。〕
リゼット：ブラム。あなた、行くあてはあるの？
ブラム：ねえよ。脱走兵に行くあてなんぞ。
リゼット：なら、荷物持ちを続けて。東までよ。
リゼット：人と人との戦を止めに行くの。
