エドモン：王は代々そうする。そういう決まりなのだ。
エドモン：それでも聞こえる。夜になると、声がする。
リゼット：声。何と言うの。
エドモン：大勢の声だ。…数えきれぬ。
エドモン：そなたは…かぶらずに済めば、よいが…。
