ヴァルド：渡し守、と言ったな。
カイ：…ああ。
ヴァルド：その方を、岸へ渡してはならぬ。
カイ：乗せた客は、岸まで渡す。
ヴァルド：ならば、その岸がどこか、よく見ておくことだ。
リゼット：行きましょう、カイ。耳を貸さないで。
〔遠くで城兵の笛。一行は隠し戸へ走る。ヴァルドは追わない。〕
ヴァルド：…姫よ。
