// 札を贈る（札の卓が次に開いたとき、手札に入る）
function giftCard(id) { try { const a = JSON.parse(localStorage.getItem("rpgCardGift") || "[]"); a.push(id); localStorage.setItem("rpgCardGift", JSON.stringify(a)); } catch (e) {} }

// ---------- 場面14　通夜小屋 ----------
