ジャコ：はは。おっかねえ喪主だ。
ジャコ：だが、ただ乗りは性に合わねえ。賽で決めようぜ。
ジャコ：あんたらが勝てば、泣き賃はただ。
ジャコ：おれが勝てば、十四枚きっちり払ってもらう。
ムク：さい？
ジャコ：通夜の賽さ。王都じゃ通夜に賽を振るんだ。
ジャコ：仏さんが退屈しねえように、夜明けまでな。
