// ---------- 寄り道の仲間トビー（鉄門砦の新兵）：手紙をミルナの母ネルに届け、返事を持って戻ると加わる ----------
const tobyHi = () => BT.HEROES.findIndex(h => h.id === "toby");
T.toby = async () => {
  const tl = G().tools;
  if (tl.nelReply) {
    await talk(`
トビー：あ！戻ってきてくれたんですか！
トビー：母は…母は、何か言ってましたか。
〔カイが返事と襟巻きを渡す。トビーが返事を開く。〕
〔返事の字：「手が震えていても、目はいいでしょう。前を見なさい。母」〕
トビー：……。
トビー：…ばれてた。震えてるの。
〔トビーが襟巻きを首に巻く。兜がずり落ちる。押し上げる。〕
トビー：ぼく、目だけはいいんです。砦の上から、すごく遠くまで見える。
トビー：でも、見張り台にいても、震えてるだけで。
トビー：…あなたたちと一緒に行けば、怖くても、前を見られる気がする。
トビー：連れていってください。上官には、ぼくが言います。
トビー：「北の斥候に、見習いで付いていきます」って。
〔見張り台の上から、年かさの兵が顔を出す。〕
年かさの兵：聞こえたぞ、新兵。…まあいい、行ってこい。
年かさの兵：震える手で見張りをされるより、ずっとましだ。
年かさの兵：ただし、死ぬな。母さんに、わしが怒られる。`);
    delete tl.nelReply; delete tl.nelScarf;
    GS.join(tobyHi()); A.sync(); SND.se("join");
    await sys("トビーが仲間に加わった！");
    return;
  }
  if (tl.tobyLetter) { await talk(`トビー：母は、粉屋の隣の家です。そばかすの、小さい人です。`); return; }
  await talk(`
〔見張り台の下。そばかすの若い兵。大きすぎる兜が、目の上までずり落ちている。手紙を握る手が震えている。〕
トビー：あ、あの。旅の人ですよね。南へ戻ることって、ありますか。
トビー：風車の里ミルナに、母がいるんです。手紙を、届けてほしくて。
トビー：郵便の荷馬車は、北伐の荷でいっぱいで…手紙は後回しで。
トビー：…ぼく、明日から、北の見張りに回されるんです。
トビー：その前に、母に「元気だ」って伝えたくて。
トビー：…元気じゃないんですけど。手が、ずっと震えてて。`);
  if (await pick(["預かる", "今は南へ行かない"]) === 0) {
    await talk(`
カイ：預かる。
トビー：ほ、本当ですか！ありがとうございます！
トビー：母は、粉屋の隣の家です。そばかすの、小さい人です。`);
    give("tobyLetter", 1); SND.se("get"); await sys("「トビーの手紙」を預かった。");
  } else await talk(`
カイ：今は、南へは行かない。
トビー：…そう、ですよね。すみません。`);
};
// ミルナのネル（トビーの母）
T.nel = async n => {
  const tl = G().tools;
  if (tl.tobyLetter && S() < 90) {
    await talk(`
〔粉屋の隣の家。小柄なそばかすの女が、継ぎの当たった前掛けで手をふいている。〕
ネル：はい、どちらさま。…手紙？トビーから？
ネル：まあ、あの子、字が書けるようになったのね。
〔ネルが手紙を読む。途中で、口に手を当てる。読み終えて、しばらく黙っている。〕
ネル：「元気です。手も震えていません」ですって。
ネル：…嘘ね。字が、震えてるもの。
ネル：旅の人。少し、待っていてくださる？返事を書くわ。
〔ネルが机に向かう。書いては消し、書いては消し、最後に短く書く。それから、棚から毛糸の襟巻きを出す。〕
ネル：これを、あの子に。北は寒いから。
ネル：返事は、短くしたの。長いと、あの子、泣くから。`);
    delete tl.tobyLetter; give("nelReply", 1); give("nelScarf", 1); SND.se("get");
    await sys("「母の返事」と「ネルの襟巻き」を預かった。");
    return;
  }
  if (tl.nelReply) { await talk(`ネル：返事は、短くしたの。長いと、あの子、泣くから。`); return; }
  return T.tt(n);
};
