〔玉座の前に、大きな荷を下ろした爺が立ち、椅子を見上げている。〕
ブラム：…おい。あの爺さん。
トト：やあやあ、足止め仲間。こんな所で会うとはねえ。
ジャコ：なんで魔王の城に札売りがいるんだよ！
トト：商いに国境はないさ。継ぐ民は札が好きでね。
トト：よく売れるんだ。昔の王さまの札が。
〔トトが札を三枚見せる。六本腕の赤い大鬼。本の山に座る大梟。大きすぎる冠の子狐。〕
トト：暴王ギルガ。賢王ミミル。幼王ポポ。
