ネネ：王がおらん。だから四つの氏族は、ばらばらじゃ。
ネネ：軍が来ても、まとまって迎えることができん。
ネネ：降ることもできん。和を結ぶこともできん。
ネネ：降る、結ぶ、と言える者がおらんのじゃから。
ネネ：里が一つずつ、名乗りも受けずに焼かれとる。
