リゼット：おばあさま。なぜ三百年、王を立てなかったの。
ネネ：空の玉座には、空である訳があるんじゃ。
リゼット：その訳は？
ネネ：わしの口からは言えん。
ネネ：言うてええのは、空けた本人だけじゃ。`);
  // 場面5　判断
  await talk(`
〔リゼットが段の下に立ち、埃の積もった玉座を見上げる。それからカイに向き直る。〕
リゼット：カイ。
リゼット：あなたが、魔王になりなさい。
ブラム：…は？
ジャコ：おいおいおい。
ムク：カイ兄が、魔王さま？
リゼット：聞いて。戦が終わらないのは、相手がいないからよ。
リゼット：軍は「魔王を討つまで」止まれない。
リゼット：でも魔王はいない。だから、いつまでも終わらない。
リゼット：継ぐ民の方にも、和を結ぶと言える王がいない。
リゼット：王がいれば、戦は終わらせられるの。
リゼット：討たれて終わるんじゃないわ。話し合って終わるのよ。
ブラム：だからって、人間が魔王になれるのか。
〔全員がネネを見る。ネネは煙管をくわえたまま。〕
ネネ：…なれる。
ネネ：王になるのに血はいらん。掟どおりに認められればええ。
オルゴ：四氏族の長の誓いでございます。牙、翼、鱗、角。
オルゴ：四つの誓いを受けた方が、王と認められます。
オルゴ：誓いは、手の甲に印となって現れます。
リゼット：カイは継ぐ民の礼儀を知ってる。心も受け取れる。
