リゼット：大丈夫よ、ミーファ。これで本当に、戦が終わるの。
〔カイがネネを見る。〕
カイ：婆。
ネネ：わしは止めも勧めもせん。
ネネ：里が焼かれとるのは本当じゃ。その娘の話も筋は通る。
ネネ：通りすぎとるのが、気に入らんがの。
ネネ：カイ。おまえが決めな。`);
  const after = async () => talk(`
ジャコ：仏さんの次は魔王かよ。出世が早えな。
