ブラム：まあいい。斥候は、王の前を歩くもんだ。
ムク：ぼく、魔王さまの弟だ！
ネネ：一つだけ言うとく。
ネネ：王の心は、とうにこの城にはない。
ネネ：あるのは椅子と掟だけじゃ。座っても、椅子は椅子よ。
リゼット：王の心は、どこにあるの？
ネネ：さあてね。持って出た者に聞くことじゃ。
〔リゼットは何も言わず、薬箱の肩ひもを握り直す。〕`);
  const yaru = () => talk(`
カイ：…やる。
カイ：渡す相手が、増えただけだ。`);
  if (await pick(["引き受ける", "一晩、考える"]) === 0) {
    await yaru(); await after(); await T.c6s6(false);
  } else {
    await talk(`
